def main():
    by_name = {g["nome"]: g for g in GRAFICHE}
    voci = []
    for data, key, nome, alt, cap in POST:
        g = by_name[nome]
        n = len(g.get("slide") or [g])
        files = [f"{nome}.png"] if n == 1 else [f"{nome}_{i}.png" for i in range(1, n + 1)]
        for f in files:
            assert (ROOT / "novembre" / f).exists(), f
        imgs = []
        for i, f in enumerate(files):
            imgs.append({"url": RAW + f, "altText": alt if i == 0 else f"{alt} Slide {i + 1} di {n}."})
        for ch in ("li", "ig", "tt"):
            cid, svc, ora = CH[ch]
            t = cap[ch]
            assert "#tassareimilionari" in t and "@einaudieditore" in t, (key, ch)
            v = {"key": f"nov-{key}-{ch}", "channelId": cid, "service": svc,
                 "dueAt": f"{data}T{ora}:00+01:00", "text": t, "images": imgs}
            if svc == "instagram":
                v["instagramType"] = "post"
            voci.append(v)
    voci.sort(key=lambda v: v["dueAt"])
    (ROOT / "novembre" / "coda_novembre.json").write_text(json.dumps(voci, ensure_ascii=False, indent=1), encoding="utf-8")
    coda = ROOT / "ottobre" / "coda_buffer.json"
    old = json.loads(coda.read_text(encoding="utf-8"))
    old = [v for v in old if not v["key"].startswith("nov-")] + voci
    coda.write_text(json.dumps(old, ensure_ascii=False, indent=1), encoding="utf-8")
    print(len(voci), "voci di novembre;", len(old), "voci totali nella coda")


if __name__ == "__main__":
    main()
